content.query:
let RunRows = AgentOpsRunSummary_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId;
let EventRows = AgentOpsEvents_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId, Status, EventName;
let SpanRows = AgentOpsSpans_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId;
let ToolRows = union
(AgentOpsToolCalls_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId, Status, Allowed),
(AgentOpsMcpCalls_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId, Status, Allowed);
let PrivacyRows = AgentOpsPrivacy_CL
| where TimeGenerated {TimeRange}
| where base64_decode_tostring('{RunId:base64}') == '*' or RunId == base64_decode_tostring('{RunId:base64}')
| project TimeGenerated, RunId, LeakDetected;
let HealthRows = AgentOpsCollectorHealth_CL
| where TimeGenerated {TimeRange}
| project TimeGenerated, Component;
let RunsObserved = toscalar(union RunRows, EventRows, SpanRows | where isnotempty(RunId) | summarize dcount(RunId));
let EventCount = toscalar(EventRows | count);
let SpanCount = toscalar(SpanRows | count);
let NativeSpanEvents = toscalar(EventRows | where EventName == "native.span.observed" | count);
let ToolCount = toscalar(ToolRows | count);
let ToolFailures = toscalar(ToolRows | where Status in~ ("error", "failed", "failure", "denied", "blocked") or Allowed == false | count);
let PrivacyCount = toscalar(PrivacyRows | count);
let LeakSignals = toscalar(PrivacyRows | where LeakDetected == true | count);
let LastHeartbeat = toscalar(HealthRows | summarize max(TimeGenerated));
let HeartbeatMinutes = datetime_diff('minute', now(), LastHeartbeat);
union
(print Order=1, Metric="Runs observed", Value=tostring(RunsObserved), Signal="neutral", Note="distinct RunId with summary, event or span rows"),
(print Order=2, Metric="Events", Value=tostring(EventCount), Signal="neutral", Note="query-visible rows; retries may duplicate"),
(print Order=3, Metric="Spans", Value=tostring(SpanCount), Signal="neutral", Note=iff(NativeSpanEvents == 0, "query-visible span-table rows", strcat("span-table rows; ", tostring(NativeSpanEvents), " native span events counted in Events"))),
(print Order=4, Metric="Tool / MCP failure signals", Value=iff(ToolCount == 0, "not observed", tostring(ToolFailures)), Signal=iff(ToolFailures > 0, "attention", "neutral"), Note=strcat("of ", tostring(ToolCount), " tool rows; other rows: success unknown")),
(print Order=5, Metric="Privacy leak signals", Value=iff(PrivacyCount == 0, "not observed", tostring(LeakSignals)), Signal=iff(LeakSignals > 0, "attention", "neutral"), Note=iff(PrivacyCount == 0, "no receipts; leak verdict unknown", strcat("of ", tostring(PrivacyCount), " receipts; not a complete guarantee"))),
(print Order=6, Metric="Collector heartbeat", Value=iff(isnull(LastHeartbeat), "not observed", case(HeartbeatMinutes < 120, strcat(tostring(HeartbeatMinutes), " min ago"), HeartbeatMinutes < 2880, strcat(tostring(HeartbeatMinutes / 60), " h ago"), strcat(tostring(HeartbeatMinutes / 1440), " d ago"))), Signal=iff(isnull(LastHeartbeat), "neutral", iff(HeartbeatMinutes > 60, "attention", "neutral")), Note="workspace-wide; not run-filtered")
| extend Value=iff(Signal == "attention", strcat("⚠ ", Value), Value)
| order by Order asc
| take 500
